      // promised to leave untouched).
      const untouched = [
        'integration',
        'publish',
        'binaries',
        'web-spa',
        'release-provenance',
        'install-pin-bump',
        'installer-smoke',
        'watchdog',
        'binaries-pr',
        'binaries-smoke-gate',
        'ci-red-report',
